"""GigaChat Provider — owns an :class:`gigachat.GigaChat` async client.

The official ``gigachat`` SDK already handles OAuth2 token refresh, the
``RqUID`` header, the Russian Trusted Root CA via ``ca_bundle_file``, configurable
SSL verification, and transparent 401 retry. This provider is a thin lifecycle
wrapper that exposes the SDK client to :class:`GigaChatModel` and surfaces the
common configuration knobs explicitly so callers don't have to import gigachat
directly.
"""

from __future__ import annotations

import os
from enum import Enum
from typing import Literal

from gigachat import GigaChat
from pydantic_ai.providers import Provider

DEFAULT_BASE_URL = "https://gigachat.devices.sberbank.ru/api/v1"


class GigaChatScope(str, Enum):
    """OAuth scopes published by Sber for GigaChat."""

    PERS = "GIGACHAT_API_PERS"
    B2B = "GIGACHAT_API_B2B"
    CORP = "GIGACHAT_API_CORP"


class GigaChatProvider(Provider[GigaChat]):
    """Provider supplying an authenticated :class:`gigachat.GigaChat` async client.

    Resolution rules mirror the SDK's own ``GIGACHAT_*`` environment variables:

    - ``authorization_key`` falls back to ``GIGACHAT_CREDENTIALS``
    - ``scope`` falls back to ``GIGACHAT_SCOPE`` (accepts both ``PERS``/``B2B``/
      ``CORP`` shorthand and the full ``GIGACHAT_API_*`` form)
    - ``verify_ssl`` falls back to ``GIGACHAT_VERIFY_SSL_CERTS``
    - ``ca_bundle_file`` falls back to ``GIGACHAT_CA_BUNDLE_FILE``

    To plug in a pre-configured SDK client (e.g. with custom retry behaviour,
    SSL context, or a shared connection pool) pass it via ``client=``.
    """

    def __init__(
        self,
        *,
        authorization_key: str | None = None,
        scope: GigaChatScope | str | None = None,
        base_url: str = DEFAULT_BASE_URL,
        verify_ssl: bool | None = None,
        ca_bundle_file: str | None = None,
        timeout: float | None = None,
        client: GigaChat | None = None,
    ) -> None:
        if client is not None:
            self._client = client
            self._owns_client = False
            self._base_url = base_url.rstrip("/")
            return

        key = authorization_key or os.environ.get("GIGACHAT_CREDENTIALS")
        if not key:
            raise ValueError(
                "GigaChat authorization key is required: pass `authorization_key=...` "
                "or set the GIGACHAT_CREDENTIALS env var."
            )

        resolved_scope = self._resolve_scope(scope)
        resolved_verify = self._resolve_verify(verify_ssl)
        resolved_ca = ca_bundle_file or os.environ.get("GIGACHAT_CA_BUNDLE_FILE")

        self._base_url = base_url.rstrip("/")
        self._owns_client = True
        self._client = GigaChat(
            credentials=key,
            scope=resolved_scope,
            base_url=self._base_url,
            verify_ssl_certs=resolved_verify,
            ca_bundle_file=resolved_ca,
            timeout=timeout,
        )

    @staticmethod
    def _resolve_scope(scope: GigaChatScope | str | None) -> str:
        if scope is not None:
            return scope.value if isinstance(scope, GigaChatScope) else scope
        env_value = os.environ.get("GIGACHAT_SCOPE")
        if env_value:
            normalized = env_value.upper()
            try:
                return GigaChatScope[normalized].value
            except KeyError:
                # Already a fully-qualified GIGACHAT_API_* string, or a custom
                # value — pass through verbatim and let GigaChat reject it.
                return env_value
        return GigaChatScope.PERS.value

    @staticmethod
    def _resolve_verify(verify: bool | None) -> bool:
        if verify is not None:
            return verify
        env_value = os.environ.get("GIGACHAT_VERIFY_SSL_CERTS", "").lower()
        return env_value not in {"0", "false", "no"}

    @property
    def name(self) -> Literal["gigachat"]:
        return "gigachat"

    @property
    def base_url(self) -> str:
        return self._base_url

    @property
    def client(self) -> GigaChat:
        return self._client

    async def aclose(self) -> None:
        if self._owns_client:
            await self._client.aclose()
